/*
 * Push handling for the app's service worker.
 *
 * The service worker itself is generated by vite-plugin-pwa (precaching, the
 * offline app shell, runtime caches). It loads this file with importScripts,
 * so none of that changes: this only adds the two events a push needs.
 *
 *   push               shows what the server sent: { title, body, url, tag }
 *   notificationclick  opens (or focuses) the app on the page the message names
 *
 * The payload is plain text the user asked to see (a total, an account name);
 * it carries no ids, tokens or anything the page would need to act on.
 */

const APP_ICON = '/pwa-192x192.png';
const APP_BADGE = '/pwa-64x64.png';

/** A path inside this app, or '/'. Anything else a payload might name is ignored. */
function safePath(value) {
  if (typeof value !== 'string' || !value.startsWith('/') || value.startsWith('//')) return '/';
  return value.length <= 200 ? value : '/';
}

const text = (value, fallback) => (typeof value === 'string' && value.trim() ? value.slice(0, 300) : fallback);

self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = {};
  }
  // A push must always show something (userVisibleOnly), even if the body was unreadable.
  const title = text(data.title, 'Expense Tracker');
  const options = {
    body: text(data.body, ''),
    icon: APP_ICON,
    badge: APP_BADGE,
    // The same tag replaces an earlier notification instead of stacking another.
    tag: typeof data.tag === 'string' && data.tag ? data.tag.slice(0, 80) : undefined,
    data: { path: safePath(data.url) },
  };
  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const path = safePath(event.notification.data && event.notification.data.path);
  const target = new URL(path, self.location.origin).href;

  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      for (const client of windows) {
        if (!client.url.startsWith(self.location.origin)) continue;
        try {
          // Chrome and Edge can steer the open window; elsewhere focusing it is the best available.
          if ('navigate' in client) await client.navigate(target);
        } catch {
          // fall through to focusing
        }
        return client.focus();
      }
      return self.clients.openWindow(target);
    })(),
  );
});
